/**********************************/
/*  Style des tables de flexions  */
/**********************************/
table.flextable {
	clear: right;
	float: right;
	margin: 0.5em;
	margin-right: 0;
	background: inherit;
	text-align: center;
	border-collapse: collapse;
}

/* Titres de colonnes */
table.flextable th {
	padding: 0.2em ;
	background: #EEEEFF ;
	border: 1px solid #AAAACC;
}

/* Cacher la case en haut à gauche */
table.flextable .notopleft {
	background: none ;
	border: 0;
}

/* Cacher une case quelconque */
table.flextable .invisible {
	background: inherit ;
	border: 0;
}

/* Titres à gauche du tableau */
table.flextable .titre {
	padding: 0.3em ;
	background: #EEEEFF ;
	border: 1px solid #AAAACC;
	font-weight: bold;
}

/* Sous-titres du tableau */
table.flextable .sous-titre {
	padding: 0.3em ;
	background: #FAFAFF ;
	border: 1px solid #AAAACC;
	font-weight: bold;
}

/* Cellule normale du tableau */
table.flextable td {
	padding: 0.3em ;
	background: #FFFFFF;
	border: 1px solid #AAAACC;
}

/* Adjacence de contenus dans les flextables */
table.flextable .colle-gauche {
	border-left:0;
	text-align:left;
	padding-left:0;
}

table.flextable .colle-droite {
	border-right:0;
	text-align:right;
	padding-right:0;
}

/* Placement à gauche ou droite simplement */
.flextable .droite {
	text-align: right ;
}
.flextable .gauche {
	text-align: left ;
}

